INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 239, 0, 'ruRU', 'Приключения из далеких и близких стран. $bВстречи с людьми странными и чудаковатыми. $bНо если вы зададите мне вопрос, $bВы должны сначала выполнить простое задание!' FROM `quest_greeting` WHERE `ID`=239 AND `Type`=0 AND MD5(`Greeting`)='2f480abff85ce5b9aa7362fca44ad275' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=239 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 241, 0, 'ruRU', 'Послушай $gприятель:приятельница;. Меня зовут Реми.$BЯ с востока Красногорья, а сюда пришел за делом, да, за делом. У тебя не найдется дела? Не найдется?' FROM `quest_greeting` WHERE `ID`=241 AND `Type`=0 AND MD5(`Greeting`)='9ac07bb050b8b18f326bd20c8b48507d' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=241 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 265, 0, 'ruRU', 'Я уже давно предчувствовала твоё приближение, $n. На это мне указали звёзды.' FROM `quest_greeting` WHERE `ID`=265 AND `Type`=0 AND MD5(`Greeting`)='4fe0f834d0869c249ce36e65df93634c' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=265 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 272, 0, 'ruRU', 'Здравствуйте, здравствуйте!  Добро пожаловать на мою кухню, $gсэр:миледи;!  $bИменно здесь готовят все лучшие деликатесы таверны "Алый ворон".  Только вдохните этот чудесный аромат!' FROM `quest_greeting` WHERE `ID`=272 AND `Type`=0 AND MD5(`Greeting`)='3613c133d10fb333a3612a28a702c79a' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=272 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 273, 0, 'ruRU', 'Держи дверь закрытой, $c. Никогда не знаешь, когда Темные всадники пройдут здесь снова.' FROM `quest_greeting` WHERE `ID`=273 AND `Type`=0 AND MD5(`Greeting`)='edb0c0f2841769b3f48a349d0105e585' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=273 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 278, 0, 'ruRU', 'Здравствуйте, $gсэр:леди;. Присаживайтесь и если вы голодны, угощайтесь. Не обращайте внимания на мою занятость, я вас внимательно слушаю...' FROM `quest_greeting` WHERE `ID`=278 AND `Type`=0 AND MD5(`Greeting`)='fbd91e69470aaca757488cf00b8b4ef0' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=278 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 288, 0, 'ruRU', 'А?!? Ох. Ты не похож на вора из Братства Справедливости... или члена Ночного Дозора. Пожалей бедную душу, ладно?' FROM `quest_greeting` WHERE `ID`=288 AND `Type`=0 AND MD5(`Greeting`)='cde160c944dbfa975fa28c6523e27403' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=288 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 313, 0, 'ruRU', 'Добро пожаловать в Башню Азоры, юный $C. Я Теокрит.$B$BУ тебя ко мне дело? Или... у меня к тебе дело, может быть?' FROM `quest_greeting` WHERE `ID`=313 AND `Type`=0 AND MD5(`Greeting`)='079a98142902c3d586b82360916c5782' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=313 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 341, 0, 'ruRU', 'У меня нет времени на разговоры, $n. Мне нужно разобраться с этим мостом до того как пойдет дождь. Я каждый проект заканчивал вовремя, и не собираюсь прокалываться сейчас.' FROM `quest_greeting` WHERE `ID`=341 AND `Type`=0 AND MD5(`Greeting`)='b25d32aec3211496d9897374a4d9049e' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=341 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 342, 0, 'ruRU', 'Приветствую, $n. Добро пожаловать в мой скромный сад. Погода в последнее время была идеальной. Будем надеяться, что она такой сохранится до сбора урожая.' FROM `quest_greeting` WHERE `ID`=342 AND `Type`=0 AND MD5(`Greeting`)='20ca72416159a5f52470d7882bc32d55' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=342 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 381, 0, 'ruRU', 'Рад встрече, $C. Если ты здесь по делу, то возьми себе пива, и мы поговорим.' FROM `quest_greeting` WHERE `ID`=381 AND `Type`=0 AND MD5(`Greeting`)='5dfc8a754ead64dc66c66a1f4c6378b6' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=381 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 382, 0, 'ruRU', 'У меня нет времени на болтовню, гражданин, но если вы готовы помочь нам в борьбе с орками, то я найду вам применение.' FROM `quest_greeting` WHERE `ID`=382 AND `Type`=0 AND MD5(`Greeting`)='39a81aed48ca3ca4d355b9d2d303bfc9' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=382 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 392, 0, 'ruRU', 'Не пугайся, $r. Я давно покинул эту землю, но не собираюсь причинять вреда твоему роду. В свое время я был свидетелем слишком большого количества смертей. Сейчас мое единственное желание - обрести мир. Возможно, ты сможешь помочь моему делу.' FROM `quest_greeting` WHERE `ID`=392 AND `Type`=0 AND MD5(`Greeting`)='f5750745652d5c563b3db8afa90e2833' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=392 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 415, 0, 'ruRU', 'Эй, $Gприятель:мадам;, как думаешь, ты сможешь мне помочь? Я действительно в отчаянном положении...' FROM `quest_greeting` WHERE `ID`=415 AND `Type`=0 AND MD5(`Greeting`)='d603e24afcb3c4641f1969e19b60d03d' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=415 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 469, 0, 'ruRU', 'Приветствую, $c. Если ты $gодин:одна; из приспешников полковника Курцена, тогда стой где стоишь! Но если ты здесь чтобы помочь нам, тогда я слушаю...' FROM `quest_greeting` WHERE `ID`=469 AND `Type`=0 AND MD5(`Greeting`)='6fb708169eaf5de09282aafae9612ef6' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=469 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 633, 0, 'ruRU', 'Настали тёмные времена, $c... Слишком скоро мы потеряем всё... Когда Свет оставит всех, кроме тех, кто действительно ходит под Светом.' FROM `quest_greeting` WHERE `ID`=633 AND `Type`=0 AND MD5(`Greeting`)='837c54cca000c6004839ec64b745c58a' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=633 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 714, 0, 'ruRU', 'Приветствую, $c! Прекрасный день для охоты, не правда ли? У меня не большие проблемы с кабанами. Не желаешь поохотиться?' FROM `quest_greeting` WHERE `ID`=714 AND `Type`=0 AND MD5(`Greeting`)='a19cf48fc2cc91fab4c25d2b567f8d32' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=714 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 737, 0, 'ruRU', 'Ну привет. Похоже, ты не против подзаработать монет, а? По глазам вижу, что хочешь. Я Могол Кебок, слежу за операциями в Азероте, и если хочешь разбогатеть, возможно, я смогу все организовать.' FROM `quest_greeting` WHERE `ID`=737 AND `Type`=0 AND MD5(`Greeting`)='04a92ec34cac3bf9198115ee4ae21b83' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=737 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 773, 0, 'ruRU', '$C, да? Я Кразек, секретарь барона Ревилгаза. Я знаю все о том, что происходит в этих джунглях и за их пределами. Хочешь узнать текущую цену на нефть в Кабестане? Нет? Может, ищешь работу? Я могу помочь тебе в этом.' FROM `quest_greeting` WHERE `ID`=773 AND `Type`=0 AND MD5(`Greeting`)='1b250deb62e767c85d488d37ce5d010c' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=773 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 1071, 0, 'ruRU', 'Если Раг чему-то меня и научил, так это тому, что не бывает скучных заданий. Защита моста Тандола должна была быть легкой задачей. Но с основным ударом армии, сражающейся вместе с Альянсом, мы были подавлены здесь, и Дун Модр пал.' FROM `quest_greeting` WHERE `ID`=1071 AND `Type`=0 AND MD5(`Greeting`)='43cbf8ff0f9800c49bf6a46fe6285593' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=1071 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 1139, 0, 'ruRU', 'Ну привет, гражданин. Меня зовут Тупонос, Мировой судья Тупонос, если быть точным. Я отвечаю за благополучие Телсамара, и поверь мне, нам здесь всегда не помешает еще одна сильная пара рук!' FROM `quest_greeting` WHERE `ID`=1139 AND `Type`=0 AND MD5(`Greeting`)='52b5168f48f1f9adad245e8334faee53' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=1139 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 1141, 0, 'ruRU', 'Если вы здесь ради еды, то добро пожаловать! Вы не найдете более изысканной еды во всем Штормграде... или Азероте!$B$BЕсли вы здесь по другим вопросам, то, пожалуйста, будьте кратки. У меня готовится дюжина блюд, и я должен позаботиться о каждом.' FROM `quest_greeting` WHERE `ID`=1141 AND `Type`=0 AND MD5(`Greeting`)='acc4bbf6f758a1554905ba5613394037' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=1141 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 1239, 0, 'ruRU', 'Если вы готовы слушать истории, от которых у вас побегут мурашки по коже и промокнет нижнее белье, тогда налейте себе выпить и присаживайтесь рядом...' FROM `quest_greeting` WHERE `ID`=1239 AND `Type`=0 AND MD5(`Greeting`)='59967112c010622e4eaef855f167f2b7' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=1239 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 1267, 0, 'ruRU', 'Добро пожаловать в Громоварку, основанную старым добрым папочкой Аркилусом Громоваром.  Я содержу это заведение в рабочем состоянии с тех пор, как мой старший брат Гримбуз исчез в пьяном угаре несколько урожаев назад.' FROM `quest_greeting` WHERE `ID`=1267 AND `Type`=0 AND MD5(`Greeting`)='5180ea1d33326f0a4cd797a0d4f7e941' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=1267 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 1284, 0, 'ruRU', 'Приветствую, $n.' FROM `quest_greeting` WHERE `ID`=1284 AND `Type`=0 AND MD5(`Greeting`)='3ac10f056ac1fb6ff39582f68adc6915' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=1284 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 1344, 0, 'ruRU', 'Хотя мы и переживаем трудный период в этих руинах, я уверен, что это продлится недолго.  Но в то же время, я мог бы использовать кого-то вроде вас.  Не хотели бы вы помочь Гильдии гномов-исследователей?' FROM `quest_greeting` WHERE `ID`=1344 AND `Type`=0 AND MD5(`Greeting`)='9312ac6b357ec5e276d305779d9a71a8' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=1344 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 1356, 0, 'ruRU', 'Я провожу очень важное геологическое исследование. Если твоё дело не столь же важное, в чем я не сомневаюсь, то не отвлекай меня.' FROM `quest_greeting` WHERE `ID`=1356 AND `Type`=0 AND MD5(`Greeting`)='4c3a56ac7fe32f63cb0e90170be88ecd' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=1356 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 1374, 0, 'ruRU', 'Проклятая лига пивоваров! У них есть все лучшие ингредиенты, в то время как мы застряли здесь с зерном и шишками хмеля!' FROM `quest_greeting` WHERE `ID`=1374 AND `Type`=0 AND MD5(`Greeting`)='27c0ccf7209a1d94295e9b92f8b5d697' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=1374 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 1377, 0, 'ruRU', 'Приветствую, $n.' FROM `quest_greeting` WHERE `ID`=1377 AND `Type`=0 AND MD5(`Greeting`)='3ac10f056ac1fb6ff39582f68adc6915' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=1377 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 1719, 0, 'ruRU', 'Ну давайте, нападайте, ничтожества!...$B$BЭй $gпарень:девчёнка;, если хочешь сделать что-то полезное, слушай скорее!' FROM `quest_greeting` WHERE `ID`=1719 AND `Type`=0 AND MD5(`Greeting`)='f9aa2d23aca5c413d560408cebe9cce9' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=1719 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 2080, 0, 'ruRU', 'Создание Тельдрассила было огромным достижением, но теперь, чтобы восстановить равновесия, мир должен измениться.' FROM `quest_greeting` WHERE `ID`=2080 AND `Type`=0 AND MD5(`Greeting`)='f2836c2bac4eeb4480252d8dac50b3b1' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=2080 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 2083, 0, 'ruRU', 'Как и сам Тельдрассил, Доланаар принимает тех, кто принимает эту землю.' FROM `quest_greeting` WHERE `ID`=2083 AND `Type`=0 AND MD5(`Greeting`)='5ebf0196ab30b25f7384c17072249d52' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=2083 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 2086, 0, 'ruRU', 'Приветствую, $n.' FROM `quest_greeting` WHERE `ID`=2086 AND `Type`=0 AND MD5(`Greeting`)='3ac10f056ac1fb6ff39582f68adc6915' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=2086 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 2092, 0, 'ruRU', 'Осадные машины – гордость каждого пилота!' FROM `quest_greeting` WHERE `ID`=2092 AND `Type`=0 AND MD5(`Greeting`)='1cc483af8318ea30f96da34a2b2c8aff' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=2092 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 2094, 0, 'ruRU', 'Приветствую, $c. Я сейчас в затруднительном положении, шкуры у меня заканчиваются.' FROM `quest_greeting` WHERE `ID`=2094 AND `Type`=0 AND MD5(`Greeting`)='17d336bdd0c91e33602929adbbd8900b' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=2094 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 2263, 0, 'ruRU', 'Надеюсь, ты здесь, чтобы работать, $C. У нас много дел, а Орда, Синдикат и Огры нам не помогут.' FROM `quest_greeting` WHERE `ID`=2263 AND `Type`=0 AND MD5(`Greeting`)='9fea3cfc63e49aac1af185ad92301dc3' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=2263 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 2276, 0, 'ruRU', 'Когда мне впервые предложили должность мирового судьи Южнобережья, я был восхищен тем, что добился этого в столь раннем возрасте.$B$BНо теперь, когда я здесь, мне интересно, не лучше ли было бы перебирать бумаги в Штормграде.' FROM `quest_greeting` WHERE `ID`=2276 AND `Type`=0 AND MD5(`Greeting`)='227747d25036e57b1a2cdbd60ab44f74' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=2276 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 2700, 0, 'ruRU', 'Мы в Опорном пункте владеем одним из немногих оставшихся участков территории Стромгарда в Нагорье Арати. И мы теряем позиции ...$B$BЕсли Вам есть что сказать, надеюсь, что это что-то хорошее.' FROM `quest_greeting` WHERE `ID`=2700 AND `Type`=0 AND MD5(`Greeting`)='629b4237387e6015c7b6e4d0003f3a9f' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=2700 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 2713, 1, 'ruRU', 'На этой деревянной доске висят грубо сделанные плакаты с надписью «Разыскивается».' FROM `quest_greeting` WHERE `ID`=2713 AND `Type`=1 AND MD5(`Greeting`)='b80d9b36f185b6bded3345f7b64b6ddb' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=2713 AND x.`type`=1 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 2785, 0, 'ruRU', 'Уходи! Назад! У меня есть пачка взрывного порошка, и я не побоюсь ее использовать! Я нас взорву!$B$BОй, извини. Я тебя кое с кем спутал...' FROM `quest_greeting` WHERE `ID`=2785 AND `Type`=0 AND MD5(`Greeting`)='7a5f9705577c1a215d87939a6eba3be5' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=2785 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 2786, 0, 'ruRU', 'Добро пожаловать в "Руны и Могучие Знания Костохвата", $C. Вы можете осмотреться здесь, но ничего не трогайте!$B$BНекоторые знания не предназначены для... непосвященных.' FROM `quest_greeting` WHERE `ID`=2786 AND `Type`=0 AND MD5(`Greeting`)='0d9c7d992d5c2c7bd0db21a1d27ac91a' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=2786 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 2860, 0, 'ruRU', 'Это была настоящая бойня, скажу я тебе, $C. Мы схватили всё, что не было прибито и бежали со всех ног. Из-за этого припасов у нас осталось с гулькин нос.' FROM `quest_greeting` WHERE `ID`=2860 AND `Type`=0 AND MD5(`Greeting`)='72d8fe2f13fe0a6d0886364ac9800643' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=2860 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 2910, 0, 'ruRU', 'Эти негодяи застали нас врасплох, напав ночью. Немногим удалось уцелеть в той заварушке...' FROM `quest_greeting` WHERE `ID`=2910 AND `Type`=0 AND MD5(`Greeting`)='e492321c90aa892e50a7f6c0ea749d0e' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=2910 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 2920, 0, 'ruRU', 'Привет, $N.$B$BЛотвиль - не самый проницательный босс, который у меня был. Он действительно вовлечён в свою работу. Настолько, что иногда его слуги не едят, или им не платят.$B$B<Люсьен хмуро смотрит на Лотвиля.>$B$BНо это не значит, что вы должны страдать.' FROM `quest_greeting` WHERE `ID`=2920 AND `Type`=0 AND MD5(`Greeting`)='03a1af6cb68539beb66429ba6459d7aa' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=2920 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 2921, 0, 'ruRU', 'Как прекрасно с твоей стороны, $C.$B$BМеня зовут Лотвиль Вериатус, член-основатель Просвещенного собрания арканологии, алхимии и инженерных наук: мы стремимся объединить интеллектуальные науки Азерота в одну общеобразовательную школу.' FROM `quest_greeting` WHERE `ID`=2921 AND `Type`=0 AND MD5(`Greeting`)='6d57eccc6b3ff1b4e0cdb0fc49b1b6b7' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=2921 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 3391, 0, 'ruRU', 'Тралл хорошо заплатил мне и моим парням за помощь в строительстве Оргриммара, поэтому я решил построить здесь порт. Мы ведем большую часть нашего бизнеса через Пиратскую Бухту и Барона Ревилгаза.' FROM `quest_greeting` WHERE `ID`=3391 AND `Type`=0 AND MD5(`Greeting`)='bf114a13d87cbe3dedb191bca2e86404' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=3391 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 3446, 0, 'ruRU', 'Да, да, да! Ты именно тот $r, которого я ищу!$B$BСадись! Нам нужно многое обсудить!!' FROM `quest_greeting` WHERE `ID`=3446 AND `Type`=0 AND MD5(`Greeting`)='782a76592731fffed76155848d70f954' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=3446 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 3453, 0, 'ruRU', 'Чем я могу вам помочь, $n? Если ничем, то я должен позаботиться об отправке.' FROM `quest_greeting` WHERE `ID`=3453 AND `Type`=0 AND MD5(`Greeting`)='87dd13e3b52100bac6b26859f6c6274c' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=3453 AND x.`type`=0 AND x.`locale`='ruRU');
