INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 5638, 0, 'ruRU', 'У меня много дел здесь, в Пустошах, $N. Ройттен хочет, чтобы мы раздобыли кое-какие реагенты для одного из наших клиентов, а также доставили некоторые из этих потерянных вещей.$B$BПоскольку вы здесь, чтобы помочь, почему бы нам не начать?' FROM `quest_greeting` WHERE `ID`=5638 AND `Type`=0 AND MD5(`Greeting`)='23fecb5584bd7b429f38d5cb1ebfb524' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=5638 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 6031, 0, 'ruRU', 'Некоторые не выносят жара в Большой кузнице, но я думаю, что жар в самый раз.  И это лучшее место для серьезных кузнечных работ.' FROM `quest_greeting` WHERE `ID`=6031 AND `Type`=0 AND MD5(`Greeting`)='a5e53a215cf886c71d54823538b11991' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=6031 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 6569, 0, 'ruRU', 'Там, где бродят трогги и гномы-прокаженные, стоит наш дом - Гномереган. $b$bНаши семьи потеряны, наши дома покинуты. Рассеяны. $b$bБоже, как я тоскую по дням беззаботной гномереганской жизни, но тех дней больше нет. Мы должны настоять на своем! Мы должны спасти Гномереган!' FROM `quest_greeting` WHERE `ID`=6569 AND `Type`=0 AND MD5(`Greeting`)='21b633db736ff466648abf82039d4266' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=6569 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 6579, 0, 'ruRU', 'За Гномреган!' FROM `quest_greeting` WHERE `ID`=6579 AND `Type`=0 AND MD5(`Greeting`)='837fde41be2389d46c92b3bb97a2d5e4' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=6579 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 7876, 0, 'ruRU', 'Некоторые люди задаются вопросом, что мы делаем здесь, в пустыне. Что ж... Если я расскажу тебе, то ты останешься и лишишь нас прибыли!' FROM `quest_greeting` WHERE `ID`=7876 AND `Type`=0 AND MD5(`Greeting`)='e22fd352fb7fcd9409ced2dea4994471' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=7876 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 7900, 0, 'ruRU', 'Привет, $N. Может быть, у тебя есть время поболтать?' FROM `quest_greeting` WHERE `ID`=7900 AND `Type`=0 AND MD5(`Greeting`)='280bf0e32a1fc99ed089bc88f3175cef' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=7900 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 9177, 0, 'ruRU', 'Встань по стойке смирно, солдат! $b$bВИНКИ! ВЫКЛЮЧИ ЗВУК!' FROM `quest_greeting` WHERE `ID`=9177 AND `Type`=0 AND MD5(`Greeting`)='827c0c95f39e6137769ea707d6b312b4' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=9177 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 9536, 0, 'ruRU', 'Поиск сокровища – единственная значимая цель для гоблина.$B$BНу, может, сокровища... и большая, громкая смерть!' FROM `quest_greeting` WHERE `ID`=9536 AND `Type`=0 AND MD5(`Greeting`)='47647f127b4500e1b7d02b9e578a4b83' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=9536 AND x.`type`=0 AND x.`locale`='ruRU');
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) SELECT 10260, 0, 'ruRU', 'Добро пожаловать в экзотический питомник Киблера! Чем вы можете мне сегодня помочь?' FROM `quest_greeting` WHERE `ID`=10260 AND `Type`=0 AND MD5(`Greeting`)='a92ebe77a058d783d56880d39177d30b' AND NOT EXISTS (SELECT 1 FROM `quest_greeting_locale` x WHERE x.`ID`=10260 AND x.`type`=0 AND x.`locale`='ruRU');
